def seed_units(apps, schema_editor):
    """Seed the canonical units of measure (idempotent)."""
    UnitOfMeasure = apps.get_model("catalog", "UnitOfMeasure")
    units = [
        ("Kilogram", "kg", "kg", 10),
        ("Gram", "g", "g", 20),
        ("Tonne", "tonne", "t", 30),
        ("Bag", "bag", "bag", 40),
        ("Crate", "crate", "crate", 50),
        ("Litre", "litre", "L", 60),
        ("Piece", "piece", "pc", 70),
        ("Bunch", "bunch", "bunch", 80),
        ("Carton", "carton", "carton", 90),
    ]
    for name, code, symbol, sort_order in units:
        UnitOfMeasure.objects.get_or_create(
            code=code, defaults={"name": name, "symbol": symbol, "sort_order": sort_order}
        )


def backfill_category_paths(apps, schema_editor):
    """Recompute ``path``/``depth`` for any pre-existing categories (idempotent)."""
    Category = apps.get_model("catalog", "Category")
    progress = True
    while progress:
        progress = False
        for category in Category.all_objects.all().iterator():
            if category.parent_id:
                parent = Category.all_objects.filter(pk=category.parent_id).first()
                new_path = f"{parent.path}{parent.pk}/" if parent else ""
                new_depth = parent.depth + 1 if parent else 0
            else:
                new_path, new_depth = "", 0
            if category.path != new_path or category.depth != new_depth:
                category.path = new_path
                category.depth = new_depth
                category.save(update_fields=["path", "depth"])
                progress = True


